sys_script_include.script:
var templateAjax = Class.create();
templateAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getDefaultReplyOptions: function() {
		var table = this.getParameter('sysparm_table');
		var replyOpt = new GlideRecordSecure('x_onpr_onpage_onpage_reply_options');
		replyOpt.addQuery('recipient_type', "direct_reference");
		replyOpt.addQuery('default', true);
		replyOpt.addQuery('table', table);
		replyOpt.query();
		if(replyOpt.next()){
			return replyOpt.getUniqueValue();
		} else return '';
    },

    type: 'templateAjax'
});
